components.css:
.ds-sheet {
  --ds-field: #efc400; --ds-ink: #14120a; --ds-ink-2: #463f2a; --ds-rule: 3px;
  background: var(--ds-field); color: var(--ds-ink);
  font-family: 'Barlow Signage', 'Helvetica Neue', Arial, sans-serif;
  font-size: 16px; line-height: 1.55; overflow-x: hidden;
  padding: 16px clamp(18px, 4.6vw, 76px) clamp(56px, 8vw, 120px);
}
.ds-sheet__inner { max-width: 1440px; margin: 0 auto; }
.ds-field { border-top: var(--ds-rule) solid var(--ds-ink); padding: clamp(30px, 4.4vw, 62px) 0 clamp(34px, 4.6vw, 66px); }
.ds-field--first { border-top: 0; }
.ds-field__id {
  font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; font-weight: 700;
  letter-spacing: 0.14em; text-transform: uppercase; background: var(--ds-ink); color: var(--ds-field);
  padding: 4px 9px 3px; white-space: nowrap;
}
.ds-display {
  font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-weight: 700;
  font-size: clamp(1.85rem, 4vw, 3.1rem); line-height: 0.95; letter-spacing: -0.005em;
  text-transform: uppercase; margin: 12px 0 0;
}
.ds-body { color: var(--ds-ink-2); max-width: 66ch; margin: 10px 0 0; }
.ds-sheet ::selection { background: var(--ds-ink); color: var(--ds-field); }

.ds-signal {
  display: flex; flex-wrap: wrap; align-items: stretch;
  border: 3px solid #14120a; margin-bottom: clamp(24px, 3.4vw, 46px);
}
.ds-signal__word {
  font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif;
  font-size: clamp(1.35rem, 2.6vw, 2.05rem); font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.02em; line-height: 1; padding: 12px 20px 10px;
  background: #0b5da7; color: #ffffff; display: flex; align-items: center;
}
.ds-signal__text {
  flex: 1 1 320px; padding: 12px 20px 10px; display: flex; align-items: center; flex-wrap: wrap; gap: 8px 16px;
  font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px;
  letter-spacing: 0.14em; text-transform: uppercase; color: #14120a;
  border-left: 1px solid rgba(20, 18, 10, 0.24);
}

.ds-fieldhead {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px clamp(14px, 2.4vw, 30px);
  border-top: 3px solid #14120a; padding-top: clamp(20px, 2.6vw, 34px); margin-bottom: clamp(20px, 2.6vw, 34px);
}
.ds-fieldhead__id {
  font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; font-weight: 700;
  letter-spacing: 0.14em; text-transform: uppercase; background: #14120a; color: #efc400; padding: 4px 9px 3px;
  white-space: nowrap;
}
.ds-fieldhead__title {
  flex: 1 1 260px; margin: 0; font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif;
  font-weight: 700; font-size: clamp(1.85rem, 4vw, 3.1rem); line-height: 0.95; letter-spacing: -0.005em;
  text-transform: uppercase;
}
.ds-fieldhead__aside {
  margin: 0 0 0 auto; text-align: right; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace;
  font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: #524a2f;
}

.ds-btn {
  display: inline-flex; align-items: center; gap: 10px;
  font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif;
  font-size: 1.12rem; font-weight: 700; letter-spacing: 0.03em; text-transform: uppercase;
  padding: 13px 22px 12px; border: 3px solid #14120a; background: #14120a; color: #efc400;
  border-radius: 0; text-decoration: none; cursor: pointer;
  transition: background-color 160ms cubic-bezier(0.16, 1, 0.3, 1), color 160ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-btn:hover { background: #efc400; color: #14120a; }
.ds-btn:focus-visible { background: #efc400; color: #14120a; outline: 3px solid #14120a; outline-offset: 3px; }

.ds-btn-ghost {
  display: inline-flex; align-items: center; gap: 10px;
  font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif;
  font-size: 1.12rem; font-weight: 700; letter-spacing: 0.03em; text-transform: uppercase;
  padding: 13px 22px 12px; border: 3px solid #14120a; background: transparent; color: #14120a;
  border-radius: 0; text-decoration: none; cursor: pointer;
  transition: background-color 160ms cubic-bezier(0.16, 1, 0.3, 1), color 160ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-btn-ghost:hover { background: #14120a; color: #efc400; }
.ds-btn-ghost:focus-visible { background: #14120a; color: #efc400; outline: 3px solid #14120a; outline-offset: 3px; }

.ds-actline {
  display: flex; flex-wrap: wrap; align-items: center; gap: clamp(14px, 2.4vw, 30px);
  margin-top: clamp(30px, 4vw, 54px); padding-top: clamp(18px, 2.4vw, 28px); border-top: 3px solid #14120a;
}
.ds-guarantee {
  margin: 0 0 0 auto; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace;
  font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: #463f2a;
}
.ds-btn, .ds-btn-ghost {
  display: inline-flex; align-items: center; gap: 10px; border: 3px solid #14120a; border-radius: 0;
  font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-size: 1.12rem; font-weight: 700;
  letter-spacing: 0.03em; text-transform: uppercase; padding: 13px 22px 12px; cursor: pointer; text-decoration: none;
  transition: background-color 160ms cubic-bezier(0.16, 1, 0.3, 1), color 160ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-btn { background: #14120a; color: #efc400; }
.ds-btn:hover, .ds-btn:focus-visible { background: #efc400; color: #14120a; }
.ds-btn-ghost { background: transparent; color: #14120a; }
.ds-btn-ghost:hover, .ds-btn-ghost:focus-visible { background: #14120a; color: #efc400; }
.ds-btn:focus-visible, .ds-btn-ghost:focus-visible { outline: 3px solid #14120a; outline-offset: 3px; }

.ds-plate {
  --ds-plate: #14120a; --ds-ink: #f6d64a; --ds-ink-2: #c9b478; --ds-hair: rgba(246, 214, 74, 0.34);
  background: var(--ds-plate); color: var(--ds-ink); border-radius: 0;
  padding: clamp(14px, 1.8vw, 22px) clamp(15px, 1.9vw, 24px) clamp(14px, 1.8vw, 20px);
}
.ds-plate__head {
  display: flex; justify-content: space-between; gap: 14px; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace;
  font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; padding-bottom: 10px; border-bottom: 1px solid var(--ds-hair);
}
.ds-plate__head span:last-child { color: var(--ds-ink-2); }
.ds-plate__state {
  margin: 11px 0 2px; font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif;
  font-size: clamp(1.9rem, 3.6vw, 2.8rem); font-weight: 700; line-height: 1; text-transform: uppercase;
}
.ds-plate__sub { margin: 0; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ds-ink-2); }
.ds-plate__readout { display: flex; align-items: flex-end; gap: 12px; margin: clamp(10px, 1.4vw, 16px) 0 10px; }
.ds-plate__value { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-variant-numeric: tabular-nums; font-weight: 700; font-size: clamp(2.4rem, 5.4vw, 3.6rem); line-height: 0.9; letter-spacing: -0.02em; }
.ds-plate__unit { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 1.05rem; font-weight: 500; padding-bottom: 4px; }
.ds-scale__track { position: relative; height: 30px; border-bottom: 1px solid var(--ds-hair); }
.ds-scale__ticks { position: absolute; inset: 0 0 auto 0; height: 9px; background-image: repeating-linear-gradient(to right, var(--ds-hair) 0 1px, transparent 1px calc(100% / 12)); }
.ds-scale__fill { position: absolute; left: 0; bottom: 0; height: 5px; background: var(--ds-ink); }
.ds-scale__mark { position: absolute; bottom: -4px; width: 2px; height: 15px; background: var(--ds-ink); }
.ds-scale__legend { display: flex; justify-content: space-between; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ds-ink-2); padding-top: 8px; }
.ds-grid4 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1px; background: var(--ds-hair); border: 1px solid var(--ds-hair); margin: 12px 0 0; }
.ds-grid4 > div { background: var(--ds-plate); padding: 9px 11px 10px; }
.ds-grid4 dt { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ds-ink-2); margin: 0 0 6px; }
.ds-grid4 dd { margin: 0; display: flex; align-items: baseline; gap: 7px; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-variant-numeric: tabular-nums; font-size: 1.06rem; font-weight: 500; }
.ds-grid4 dd em { font-style: normal; font-size: 0.78rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ds-ink-2); }

.ds-selector { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; margin-bottom: 18px; }
.ds-selector__label { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: #524a2f; }
.ds-range {
  -webkit-appearance: none; appearance: none; flex: 1 1 200px; min-width: 0; width: 100%; height: 26px;
  background: transparent; cursor: ew-resize; margin: 0;
}
.ds-range::-webkit-slider-runnable-track {
  height: 26px; border-top: 1px solid rgba(20, 18, 10, 0.24); border-bottom: 1px solid rgba(20, 18, 10, 0.24);
  background-image: repeating-linear-gradient(to right, rgba(20, 18, 10, 0.24) 0 1px, transparent 1px 4.1667%);
}
.ds-range::-moz-range-track {
  height: 26px; border-top: 1px solid rgba(20, 18, 10, 0.24); border-bottom: 1px solid rgba(20, 18, 10, 0.24);
  background-image: repeating-linear-gradient(to right, rgba(20, 18, 10, 0.24) 0 1px, transparent 1px 4.1667%);
}
.ds-range::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 12px; height: 34px; margin-top: -4px; background: #14120a; border: 0; border-radius: 0; }
.ds-range::-moz-range-thumb { width: 12px; height: 34px; background: #14120a; border: 0; border-radius: 0; }
.ds-range:focus-visible { outline: 3px solid #14120a; outline-offset: 3px; }
.ds-range__value { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-variant-numeric: tabular-nums; font-size: 1.05rem; font-weight: 500; min-width: 5.4ch; }
.ds-btn-ghost {
  display: inline-flex; align-items: center; border: 3px solid #14120a; border-radius: 0; background: transparent; color: #14120a;
  font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-size: 1.12rem; font-weight: 700;
  letter-spacing: 0.03em; text-transform: uppercase; padding: 13px 22px 12px; cursor: pointer;
}
.ds-btn--small { padding: 7px 12px 6px; font-size: 0.86rem; }
.ds-btn-ghost:hover:not(:disabled) { background: #14120a; color: #efc400; }
.ds-btn-ghost:focus-visible { outline: 3px solid #14120a; outline-offset: 3px; }
.ds-btn-ghost:disabled { cursor: default; background: transparent; color: #524a2f; border-color: #524a2f; }

.ds-band__plot {
  position: relative; border-top: 1px solid rgba(20, 18, 10, 0.24); border-bottom: 1px solid rgba(20, 18, 10, 0.24);
  color: #14120a; background: #efc400;
}
.ds-band__plot svg { display: block; width: 100%; height: clamp(150px, 20vw, 250px); }
.ds-band__label { position: absolute; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: #463f2a; pointer-events: none; }
.ds-band__label--low { bottom: 4px; transform: translateX(-50%); }
.ds-band__mark { position: absolute; top: 0; bottom: 0; width: 2px; background: #14120a; pointer-events: none; }
.ds-band__readout {
  position: absolute; top: 10px; transform: translateX(-50%); background: #14120a; color: #efc400;
  font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.08em;
  text-transform: uppercase; padding: 5px 9px 4px; white-space: nowrap; pointer-events: none;
}
.ds-band__legend { display: flex; flex-wrap: wrap; gap: 10px clamp(14px, 2.4vw, 30px); margin-top: clamp(14px, 1.8vw, 22px); padding-top: 14px; border-top: 1px solid rgba(20, 18, 10, 0.24); }
.ds-legend { display: flex; align-items: baseline; gap: 8px; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: #463f2a; }
.ds-legend__mark { display: inline-block; width: 28px; height: 14px; }
.ds-legend__mark--solid { background: #14120a; }
.ds-legend__mark--line { height: 3px; background: #14120a; }
.ds-legend__mark--surplus { background-image: repeating-linear-gradient(45deg, #14120a 0 3.4px, transparent 3.4px 8px); }
.ds-legend__mark--deficit { background-image: repeating-linear-gradient(-45deg, #14120a 0 2.2px, transparent 2.2px 8px); }
.ds-band__totals { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1px; background: rgba(20, 18, 10, 0.24); border: 1px solid rgba(20, 18, 10, 0.24); margin: clamp(20px, 2.6vw, 30px) 0 0; }
@media (min-width: 780px) { .ds-band__totals { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
.ds-band__totals > div { background: #efc400; padding: 14px 16px 16px; }
.ds-band__totals dt { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: #524a2f; margin: 0 0 8px; }
.ds-band__totals dd { margin: 0; display: flex; align-items: baseline; gap: 6px; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-variant-numeric: tabular-nums; font-size: clamp(1.4rem, 2.6vw, 1.9rem); font-weight: 500; color: #14120a; }
.ds-band__totals dd span { font-size: 0.8rem; letter-spacing: 0.06em; color: #524a2f; }

.ds-line { list-style: none; margin: 0; padding: 0; }
.ds-node {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 14px;
  border: 1px solid rgba(20, 18, 10, 0.24); padding: 12px 16px 13px; border-radius: 0; background: #efc400; color: #14120a;
}
.ds-node--source { border: 3px solid #14120a; }
.ds-node--device { border: 3px solid #14120a; background: #14120a; color: #f6d64a; }
.ds-node--device .ds-node__spec, .ds-node--device .ds-val--unit { color: #c9b478; }
.ds-node__id { font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-size: 1.32rem; font-weight: 700; line-height: 1; text-transform: uppercase; letter-spacing: 0.01em; }
.ds-node__spec { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: #524a2f; }
.ds-values { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px clamp(14px, 2.4vw, 30px); margin-left: auto; }
.ds-values__item { display: flex; align-items: baseline; gap: 7px; }
.ds-val { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-variant-numeric: tabular-nums; font-size: 1.12rem; font-weight: 500; }
.ds-val--s { font-size: 0.94rem; }
.ds-val--unit { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 0.86rem; letter-spacing: 0.06em; color: #463f2a; }

.ds-linkrow { display: grid; grid-template-columns: 74px minmax(0, 1fr); gap: clamp(12px, 2vw, 26px); align-items: center; }
.ds-linkrow__rail { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; min-height: 62px; }
.ds-linkrow__rail i { display: block; width: 3px; flex: 1 1 auto; background: #14120a; }
.ds-linkrow__rail--elbow { align-items: stretch; }
.ds-linkrow__elbow { display: block; flex: 1 1 auto; border-left: 3px solid #14120a; border-bottom: 3px solid #14120a; }
.ds-linkrow__meta { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px clamp(14px, 2.4vw, 26px); }
.ds-chip { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; font-weight: 500; letter-spacing: 0.12em; text-transform: uppercase; padding: 3px 8px 2px; white-space: nowrap; }
.ds-chip--battery { background: #c5a572; color: #14120a; }
.ds-chip--grid { background: #5d8aa8; color: #14120a; }
.ds-val { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-variant-numeric: tabular-nums; font-size: 1.12rem; font-weight: 500; color: #14120a; }
.ds-val--s { font-size: 0.94rem; }
.ds-val--unit { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 0.86rem; letter-spacing: 0.06em; color: #463f2a; }

.ds-notices { list-style: none; margin: 0; padding: 0; border-top: 1px solid rgba(20, 18, 10, 0.24); }
.ds-notice {
  display: grid; gap: 10px clamp(16px, 2.6vw, 34px); grid-template-columns: minmax(0, 1fr);
  padding: clamp(18px, 2.4vw, 26px) 0; border-bottom: 1px solid rgba(20, 18, 10, 0.24);
}
@media (min-width: 760px) { .ds-notice { grid-template-columns: 128px minmax(0, 1fr) minmax(0, 210px); } }
.ds-notice__word {
  justify-self: start; align-self: start; display: inline-block;
  font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-size: 1.28rem; font-weight: 700;
  letter-spacing: 0.02em; line-height: 1; text-transform: uppercase; padding: 6px 11px 5px; border-radius: 0;
}
.ds-notice__word--warning { background: #e2711d; color: #14120a; }
.ds-notice__word--notice { background: #0b5da7; color: #ffffff; }
.ds-notice__word--caution { background: #14120a; color: #efc400; }
.ds-notice__word--guide { background: #146b3a; color: #ffffff; }
.ds-notice__word--danger { background: #c8102e; color: #ffffff; }
.ds-notice__title { margin: 0 0 7px; font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-size: clamp(1.28rem, 2vw, 1.6rem); font-weight: 600; line-height: 1; text-transform: uppercase; }
.ds-notice__body { margin: 0; font-size: 0.97rem; line-height: 1.5; color: #463f2a; max-width: 60ch; }
.ds-notice__metric { border-left: 3px solid #14120a; padding-left: 14px; }
.ds-notice__value { display: flex; align-items: baseline; gap: 6px; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-variant-numeric: tabular-nums; font-size: 1.9rem; font-weight: 500; line-height: 1; }
.ds-notice__value span { font-size: 0.82rem; }
.ds-notice__delta { margin: 7px 0 0; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: #524a2f; }
.ds-notice__action { display: inline-block; margin: 9px 0 0; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: #14120a; text-decoration: none; border-bottom: 2px solid #14120a; padding-bottom: 2px; }
.ds-notice__action:focus-visible { outline: 3px solid #14120a; outline-offset: 3px; }

.ds-danger {
  display: grid; gap: clamp(14px, 2vw, 28px); grid-template-columns: minmax(0, 1fr); align-items: center;
  background: #c8102e; color: #ffffff; padding: clamp(18px, 2.4vw, 28px); margin-bottom: clamp(22px, 3vw, 36px); border-radius: 0;
}
@media (min-width: 820px) { .ds-danger { grid-template-columns: 128px minmax(0, 1fr) minmax(0, 0.62fr); } }
.ds-danger__word { margin: 0; font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-size: clamp(1.6rem, 3vw, 2.4rem); font-weight: 700; line-height: 1; text-transform: uppercase; }
.ds-danger__body { margin: 0; font-size: 1.02rem; line-height: 1.45; max-width: 46ch; }
.ds-danger__body strong { font-weight: 600; }
.ds-danger__note { margin: 12px 0 0; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; opacity: 0.92; }
.ds-danger__pict { width: 112px; height: 112px; justify-self: start; }
@media (min-width: 820px) { .ds-danger__pict { justify-self: end; } }

.ds-label {
  display: flex; flex-direction: column; gap: 12px; background: #efc400; color: #14120a; border-radius: 0;
  padding: clamp(16px, 2vw, 24px) clamp(16px, 2vw, 24px) clamp(18px, 2.2vw, 26px);
}
.ds-label__top { display: flex; align-items: baseline; gap: 10px; }
.ds-label__id { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; padding: 3px 7px 2px; box-shadow: inset 0 0 0 1px rgba(20, 18, 10, 0.24); white-space: nowrap; }
.ds-label__role { font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; color: #524a2f; }
.ds-label__title { margin: 0; font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-size: clamp(1.3rem, 2.1vw, 1.7rem); font-weight: 700; line-height: 1; text-transform: uppercase; }
.ds-label__body { margin: 0; font-size: 0.97rem; line-height: 1.5; color: #463f2a; max-width: 58ch; }
.ds-label__artifact { margin-top: auto; border-top: 1px solid rgba(20, 18, 10, 0.24); padding-top: 12px; }
.ds-formula { display: block; overflow-x: auto; white-space: nowrap; background: #14120a; color: #efc400; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 0.85rem; letter-spacing: 0.02em; padding: 9px 11px 8px; }

.ds-labels { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1px; background: rgba(20, 18, 10, 0.24); border: 1px solid rgba(20, 18, 10, 0.24); }
@media (min-width: 700px) { .ds-labels { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1080px) { .ds-labels { grid-template-columns: repeat(12, minmax(0, 1fr)); } .ds-label--l02 { grid-column: span 5; } .ds-label--l06 { grid-column: span 12; } }

.ds-amend {
  display: inline-block; transform: rotate(-0.55deg); transform-origin: 12% 40%;
  background: #14120a; color: #efc400; padding: 14px 18px 15px; max-width: 44ch; border-radius: 0;
  box-shadow: 0 3px 7px rgba(0, 0, 0, 0.28), 0 1px 2px rgba(0, 0, 0, 0.24);
}
.ds-amend__k { display: block; margin-bottom: 7px; opacity: 0.86; font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-amend__body { margin: 0; font-size: 0.94rem; line-height: 1.45; }
.ds-amend__body strong { font-weight: 600; }

.ds-position {
  position: fixed; top: 0; left: 0; right: 0; z-index: 5; height: 26px;
  display: flex; align-items: center; padding: 0 clamp(18px, 4.6vw, 76px); pointer-events: none;
}
.ds-position__track { position: absolute; top: 0; left: 0; right: 0; height: 3px; background: rgba(20, 18, 10, 0.24); }
.ds-position__fill { position: absolute; top: 0; left: 0; height: 3px; background: #14120a; }
.ds-position__name {
  position: relative; margin-left: auto; background: #14120a; color: #efc400; padding: 3px 8px 2px;
  font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.12em;
  text-transform: uppercase; transition: opacity 220ms cubic-bezier(0.16, 1, 0.3, 1); opacity: 1;
}

.ds-issuer__brand {
  display: flex; align-items: center; gap: 10px; color: #14120a;
  font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-size: 26px; font-weight: 700;
  letter-spacing: 0.01em; line-height: 1; text-transform: lowercase;
}
.ds-logoblock { display: grid; place-items: center; width: 34px; height: 34px; background: #0b0b0c; flex: none; border-radius: 0; }
.ds-logoblock svg { width: 26px; height: 26px; }

.ds-chips { display: flex; flex-wrap: wrap; gap: 10px; }
.ds-chip {
  font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; font-weight: 500;
  letter-spacing: 0.12em; text-transform: uppercase; padding: 3px 8px 2px; border-radius: 0; white-space: nowrap;
  background: #14120a; color: #efc400;
}
.ds-chip--solar { background: #f0c674; color: #14120a; }
.ds-chip--flow { background: #7fb069; color: #14120a; }
.ds-chip--grid { background: #5d8aa8; color: #14120a; }
.ds-chip--battery { background: #c5a572; color: #14120a; }

.ds-brand {
  display: flex; align-items: center; gap: 8px; color: #14120a;
  font-family: 'Plate Mono', ui-monospace, SFMono-Regular, monospace; font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase;
}
.ds-brand__mark {
  display: grid; place-items: center; width: 26px; height: 26px; border-radius: 0;
  font-family: 'Barlow Condensed', 'Arial Narrow', system-ui, sans-serif; font-size: 15px; font-weight: 700;
  box-shadow: inset 0 0 0 2px #14120a;
}
